CREATE TABLE 'abyss_quest_data' ('quest_id' INTEGER NOT NULL, 'abyss_id' INTEGER NOT NULL, 'difficulty' INTEGER NOT NULL, 'quest_name' TEXT NOT NULL, 'stamina' INTEGER NOT NULL, 'team_exp' INTEGER NOT NULL, 'unit_exp' INTEGER NOT NULL, 'love' INTEGER NOT NULL, 'limit_time' INTEGER NOT NULL, 'condition_quest_id' INTEGER NOT NULL, 'release_quest_id' INTEGER NOT NULL, 'wave_group_id' INTEGER NOT NULL, 'drop_gold' INTEGER NOT NULL, 'clear_reward_group' INTEGER NOT NULL, 'drop_reward_group' INTEGER NOT NULL, PRIMARY KEY('quest_id'));
